@'
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { parseManifest } from './packages/core/src/domain/manifest.ts';
import { parseSkillDocument, documentName, documentDescription } from './packages/core/src/domain/skill-document.ts';
const root=path.resolve('skills/microservices-architecture');
const files=['SKILL.md','skill.yaml','references/integrating-decisions.md'];
const parsed=parseManifest(fs.readFileSync(path.join(root,'skill.yaml'),'utf8'),{strict:true});
assert.deepEqual(parsed.issues,[]);
const main=fs.readFileSync(path.join(root,'SKILL.md'),'utf8');
const doc=parseSkillDocument(main);
assert.equal(documentName(doc),parsed.manifest.name);
assert.equal(documentDescription(doc),parsed.manifest.description);
assert.equal(parsed.manifest.version,'1.0.1');
for(const file of parsed.manifest.files) assert.ok(fs.existsSync(path.join(root,file)),file);
assert.ok(main.includes('references/integrating-decisions.md'));
assert.ok(parsed.manifest.suggests.includes('retries-and-backoff'));
for(const referral of ['timeouts-and-deadlines','retries-and-backoff']) {
  assert.ok(fs.existsSync(path.resolve(root,'..',referral,'SKILL.md')),referral);
}
let localLinks=0;
for(const file of files.filter(f=>f.endsWith('.md'))) {
 const text=fs.readFileSync(path.join(root,file),'utf8');
 for(const match of text.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)) {
  if(/^[a-z][a-z0-9+.-]*:/i.test(match[1])) continue;
  const target=path.resolve(root,path.dirname(file),match[1].split('#')[0]);
  assert.ok(target.startsWith(root+path.sep),match[1]);
  assert.ok(fs.existsSync(target),match[1]);
  localLinks++;
 }
}
console.log(JSON.stringify({version:parsed.manifest.version,strictManifestIssues:0,descriptionEqual:true,packageFiles:3,routedReferences:1,localLinks,newOptionalReferral:'retries-and-backoff',referralTargetsPresent:true}));
'@ | node --input-type=module
